css:
[data-bz-section="location-others"] .bz-block { padding-block: 0 }
/* This handoff keeps its grey and dark bands to the same 1280px well as its white ones. */
.bz-sharedsection[data-bz-section="location-others"] > .bz-section > .bz-container { max-width: var(--container) }
[data-bz-section="location-others"] .bz-block + .bz-block { padding-block-start: 0 }
[data-bz-section="location-others"] .bz-row + .bz-row { margin-top: 0 }
[data-bz-section="location-others"] h2 { font-size: 34px; line-height: 1.7; margin: 0 0 18px }
[data-bz-section="location-others"] [data-bz-node="lo2-body"] p { font-size: 16px; line-height: 1.75; color: var(--body-text); margin: 0 0 40px; max-width: 880px }
/* Handoff .loc: white cards on the grey band, four across, two at 1100px, one at 640px. */
[data-bz-section="location-others"] .bz-row[data-bz-node="lo2-grid"] { gap: 24px }
[data-bz-section="location-others"] .bz-col[data-bz-node^="lo2-card-"] { background: var(--card); border: 1px solid var(--line); padding: 28px }
[data-bz-section="location-others"] [data-bz-node^="lo2-card-h"] .bz-eyebrow { font-size: 10px; line-height: 1.3; letter-spacing: .14em; color: var(--accent); margin: 0 0 12px }
[data-bz-section="location-others"] [data-bz-node^="lo2-card-h"] h3 { font-size: 18px; line-height: 1.7; font-weight: 800; margin: 0 0 12px }
[data-bz-section="location-others"] [data-bz-node^="lo2-card-meta"] p { font-size: 14px; line-height: 1.5; color: var(--body-text); margin: 0 }
[data-bz-section="location-others"] [data-bz-node^="lo2-card-meta"] .bz-text { margin-bottom: 14px }
[data-bz-section="location-others"] .bz-btns { margin-block: 0; flex-direction: column; align-items: flex-start; gap: 8px }
[data-bz-section="location-others"] .bz-btn--link { font: 700 15px / 1.7 var(--font-body); color: var(--accent); text-transform: none; letter-spacing: 0 }
[data-bz-section="location-others"] [data-bz-node^="lo2-card-cta"] { margin-bottom: 8px }
@media (min-width: 641px) and (max-width: 1100px) { [data-bz-section="location-others"] .bz-col[data-bz-node^="lo2-card-"] { grid-column: span 6 } }
@media (max-width: 640px) { [data-bz-section="location-others"] h2 { font-size: 26px } }
